#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int S, T, P;
vector<int> A;
vector<vector<int>> adj;
vector<int> memo;

int dfs(int u) {
    if (memo[u] != -1) return memo[u];

    int max_steps = 0;
    for (int v : adj[u]) {
        max_steps = max(max_steps, 1 + dfs(v));
    }

    return memo[u] = max_steps;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> S >> T >> P)) return 0;

    A.resize(S + 1);
    for (int i = 1; i <= S; ++i) {
        cin >> A[i];
    }

    adj.resize(S + 1);
    for (int k = 0; k < T; ++k) {
        int u, v;
        cin >> u >> v;
        if (A[u] > A[v]) {
            adj[u].push_back(v);
        } else if (A[v] > A[u]) {
            adj[v].push_back(u);
        }
    }

    memo.assign(S + 1, -1);

    cout << dfs(P) << "\n";

    return 0;
}
